-- strapi-php 5.56 getstarted on MySQL (MariaDB 10.11): the admin tables and locales after
-- registering the first admin and adding a "Content Writer" role with the SQLite fixture's
-- permissions; columns the reader skips are left out.
CREATE TABLE admin_roles (id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, document_id varchar(255), name varchar(255), code varchar(255), description varchar(255));
CREATE TABLE admin_permissions (id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, document_id varchar(255), action varchar(255), action_parameters json, subject varchar(255), properties json, conditions json);
CREATE TABLE admin_permissions_role_lnk (id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, permission_id int unsigned, role_id int unsigned, permission_ord double);
CREATE TABLE i18n_locale (id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, document_id varchar(255), name varchar(255), code varchar(255));
